public static void lookupClassesExtendingCertainClass(FormControl _callingControl, ClassName _className, str _descriptionColumnHeaderText = '')
{
    SysTableLookup      sysTableLookup  = SysTableLookup::newParameters(tablenum(TFMDocumentTmpHandlerLookup), _callingControl);
    classId             classId = className2Id(_className);
    SysDictClass        dictClass = new SysDictClass(classId), subCls;
    List                extendedClasses = dictClass.extendedBy();
    ListEnumerator      lEnum = extendedClasses.getEnumerator();
    TFMDocumentTmpHandlerLookup     tmpLookup;
    anytype             subClass;

    sysTableLookup.addLookupfield(fieldNum(TFMDocumentTmpHandlerLookup,className),true);
    sysTableLookup.addLookupfield(fieldNum(TFMDocumentTmpHandlerLookup,Description));
    if(_descriptionColumnHeaderText)
    {
        sysTableLookup.setLabel(_descriptionColumnHeaderText);
    }
    tmpLookup.setTmp();

    while (lENum.moveNext())
    {
        subCls = new sysDictClass(lEnum.current());
        if ( subCls == null || subCls.isAbstract())
        {
            continue;
        }
        subClass = subCls.makeObject();

        if(subCls.hasObjectMethod(methodStr(TFMDocumentHandler, description)))
        {
            tmpLookup.Description = subClass.description();
        }
        else
        {
            tmpLookup.Description = subCls.name();
        }
        tmpLookup.ClassName = subCls.name();
        tmpLookup.insert();
    }
    sysTableLookup.parmTmpBuffer(tmpLookup);
    sysTableLookup.performFormLookup();
}

public static void lookupClasses(FormControl _callingControl)
{
    TFMFormLookupHelper::lookupClassesExtendingCertainClass(_callingControl, classStr(TFMDocumentHandler));
}

public static void lookupValidationClasses(FormControl _callingControl)
{
    SysTableLookup					sysTableLookup  = SysTableLookup::newParameters(tablenum(TmpAotImport), _callingControl);

    TmpAotImport                    tmpLookup;
    ListEnumerator			        lEnum = new SysDictClass(classNum(TFMWorkflowValidation)).extendedBy().getEnumerator();
    TFMWorkflowValidation	        validationClass;
    SysDictClass			        sdc;

    sysTableLookup.addLookupfield(fieldNum(TmpAotImport,TreeNodeName));
    sysTableLookup.addLookupfield(fieldNum(TmpAotImport,TreeNodePath),true);

    tmpLookup.setTmp();


    while (lEnum.moveNext())
    {
        sdc = new SysDictClass(lEnum.current());
        if (!sdc.allowMakeObject())
        {
            continue;
        }
        validationClass = sdc.makeObject();
        tmpLookup.TreeNodeName = validationClass.label();
        tmpLookup.TreeNodePath = validationClass.validationType();
        tmpLookup.insert();
    }

    sysTableLookup.parmTmpBuffer(tmpLookup);
    sysTableLookup.performFormLookup();
}

