    int								j;
    TFMTableNameAttribute			tableNameAttr;

    sysTableLookup.addLookupfield(fieldNum(TFMDocumentTmpHandlerLookup,className),true);
    sysTableLookup.addLookupfield(fieldNum(TFMDocumentTmpHandlerLookup,Description));

    tmpLookup.setTmp();

    if (attrArray != null)
    {
        for (j = 1; j <= attrArray.lastIndex(); j++)
        {
            tableNameAttr = attrArray.value(j);
            tmpLookup.Description = tableNameAttr.parmTableName();
            tmpLookup.ClassName = tableNameAttr.parmOrderType();
            tmpLookup.insert();
        }
    }

    sysTableLookup.parmTmpBuffer(tmpLookup);
    sysTableLookup.performFormLookup();
