public static Map getCertainPageTypes(className _pageTypeDelimitation, TFMWorkflowName _workflowDelimitation = '')
{
    Map								pagesAvailable = TFMPagesProvider::getAllPages().getPages();
    MapEnumerator					pageEnum = pagesAvailable.getEnumerator();
    TFMPages						pages;
    TFMPage							page;
    TFMPageOrderList				orderList;
    TFMPageOrderListConfiguration	conf;
    Map								returnPages = new Map(Types::String, Types::Class);

    while (pageEnum.moveNext())
    {
        page = pageEnum.currentValue();
        if (classIdGet(page) != className2Id(_pageTypeDelimitation))
        {
            //Don't add page
            continue;
        }
        if (_workflowDelimitation && classIdGet(page) == classNum(TFMPageOrderList))
        {
            orderList = page;
            conf = orderList.getConfiguration();
            if (conf.parmWorkflowName() != _workflowDelimitation)
            {
                continue;
            }
        }
        returnPages.insert(page.parmId(), page);
    }

    return returnPages;
}

