public static void lookupDocumentTypes(FormControl _callingControl)
{
    SysTableLookup					  sysTableLookup  = SysTableLookup::newParameters(tablenum(TmpAotImport), _callingControl);
    TmpAotImport				      tmpLookup;

    SetEnumerator docHandlersTypesEnum =   TFMDocumentTypeProvider::instance().getTypes().getEnumerator();
    Set addedTypes = new Set(Types::String);

    sysTableLookup.addLookupfield(fieldnum(TmpAotImport, TreeNodeName),true);

    tmpLookup.setTmp();
    while (docHandlersTypesEnum.moveNext())
    {       
        str docType = docHandlersTypesEnum.current();
        if(!addedTypes.in(docType))
        {
            tmpLookup.TreeNodeName = docType;
            tmpLookup.TreeNodePath = docType;
            tmpLookup.insert();

            addedTypes.add(docType);
        }

    }
    // BP deviation documented
    sysTableLookup.parmTmpBuffer(tmpLookup);
    sysTableLookup.performFormLookup();
}

