public static Map getConfigurableFilters(str _filterDelimitation = '', boolean _returnObject = false)
{
    SysDictClass					dictClass = new SysDictClass(classNum(TFMDocumentHandler)), subCls;
    List							extendedClasses = dictClass.extendedBy(true);
    ListEnumerator					lEnum = extendedClasses.getEnumerator();
    TFMDocumentHandler				docHand;

    Set								methodSet;
    Set								otherSet;
    SetEnumerator					sEnum;
    MapEnumerator					mEnum;
    MethodName						methodName;
    anytype							retVal;
    TFMReferenceDataConfiguration	refData;
    TFMReferenceDataMethodAttribute refDataAttribute = new TFMReferenceDataMethodAttribute();
    Map								filters = new Map(Types::String, _returnObject ? Types::Class : Types::String);

    while (lENum.moveNext())
    {
        subCls = new sysDictClass(lEnum.current());
        if ( subCls == null || subCls.isAbstract())
        {
            continue;
        }
        docHand = subCls.makeObject() as TFMDocumentHandler;
        methodSet = docHand.getReferenceDataMethods();

        if (methodSet == null)
        {
            methodSet = new Set(Types::String);
        }
        otherSet = new Set(Types::String);
        mEnum = TFMAttributeHandler::getMethodNamesFromSysAttribute(subCls.id(),refDataAttribute).getEnumerator();
        while (mEnum.moveNext())
        {
            otherSet.add(mEnum.currentKey());
        }
        methodSet = Set::union(methodSet,otherSet);

        sEnum  = methodSet.getEnumerator();
        while (sEnum.moveNext())
        {
            try
            {
                methodName = sEnum.current();

                if ((SysTest::hasMethod(docHand, methodName)))
                {
                    retVal = subCls.callObject(methodName,docHand);
                    if (typeOf(retVal) == Types::Class && classIdGet(retVal) == classNum(TFMReferenceDataConfiguration))
                    {
                        refData = retVal;
                        refData.parmKey(refData.parmKey() ? refData.parmKey() : MethodName);
                        if ((refData.parmUseDynaFilter() && !_filterDelimitation) || _filterDelimitation == methodName)
                        {
                            filters.insert(classId2Name(classIdGet(docHand))+'.'+methodName + '()', (_returnObject ? retVal : refData.parmKey()));
                        }
                        else if (refData.getInlinedHeaders().exists(_filterDelimitation))
                        {
                            filters.insert(classId2Name(classIdGet(docHand))+'.'+_filterDelimitation + '()', (_returnObject ? retVal : _filterDelimitation));
                        }
                    }
                    else if (_filterDelimitation == methodName)
                    {
                        filters.insert(classId2Name(classIdGet(docHand))+'.'+methodName + '()', _returnObject ? retVal : methodName);
                    }

                }

            }
            catch (Exception::Error)
            {
                continue;
            }
        }

    }
    return filters;
}

public static Map getConfigurableFilterFields(str _methodName)
{
    str								filterStr = _methodName;
    str								clsName = subStr(filterStr,1,strScan(filterStr,'.',1,strLen(filterStr))-1);
    str								mthdName= subStr(filterStr,strScan(filterStr,'.',1,strLen(filterStr))+1,strLen(filterStr));
    Map								returnMap = new Map(Types::String, Types::Class);
    SysDictClass					DC = new SysDictClass(className2Id(clsName));
    TFMRegistrationCollector		collector;
    SetEnumerator					collectors;
    TFMReferenceDataConfiguration	filterConfig;
    anytype							result;

    result = DC.callObject(mthdName,DC.makeObject());
    if (typeOf(result) != Types::Class)
    {
        return returnMap;
    }
    filterConfig = result;
    filterConfig.parmKey(filterConfig.parmKey() ? filterConfig.parmKey() : mthdName);
    collectors = filterConfig.getCollectors().getEnumerator();
    while (collectors.moveNext())
    {
        collector = collectors.current();
        returnMap.insert(collector.parmName(),collector);
    }

    return returnMap;
}

