public static void lookupDatasetFields(FormControl _callingControl, TFMListId _listId, boolean _addBrackets, TFMPageDatasources _datasources)
{
    TFMList                         list = TFMListsProvider::getAllLists().getList(_listId);
    MapEnumerator					fields = TFMListVisualization::findDataset(list, _dataSources).getEnumerator();
    SysTableLookup					sysTableLookup  = SysTableLookup::newParameters(tablenum(TmpTableName), _callingControl);
    TmpTableName					tmpLookup;
    str								preFix = _addBrackets ? '{' : '';
    str								postFix = _addBrackets ? '}' : '';
    int								i;
    sysTableLookup.addLookupfield(fieldNum(TmpTableName,TableName),true);

    while (fields.moveNext())
    {
        tmpLookup.TableName	= preFix + fields.currentKey() + postFix;
        tmpLookup.insert();
        i++;
    }

    sysTableLookup.parmTmpBuffer(tmpLookup);
    sysTableLookup.performFormLookup();
}

public static void lookupEDTfields(FormControl _callingControl)
{
    SysTableLookup                  sysTableLookup  = SysTableLookup::newParameters(tablenum(TFMPagesEDTTmpLookup), _callingControl);
    TFMPagesEDTTmpLookup            tmpLookup;
    MapEnumerator                   mEnum = TFMPagesProvider::getAllPages().getPages().getEnumerator();
    TFMPage                         page;
    Map                             headersMap = TFMHeadersProvider::GetPageHeaders();
    TFMReferenceDataConfiguration   refData;
    SetEnumerator                   sEnum;
    TFMRegistrationCollector        collector;

    sysTableLookup.addLookupfield(fieldNum(TFMPagesEDTTmpLookup,EDTBasedOn),true);
    sysTableLookup.addLookupfield(fieldNum(TFMPagesEDTTmpLookup,PageID));
    sysTableLookup.addLookupfield(fieldNum(TFMPagesEDTTmpLookup,Title));
    sysTableLookup.addLookupfield(fieldNum(TFMPagesEDTTmpLookup,FieldName));

    tmpLookup.setTmp();

    while (mEnum.moveNext())
    {

        page = mEnum.currentValue();
        if (!headersMap.exists(page.parmFilter()))
        {
            continue;
        }
        refData = headersMap.lookup(page.parmFilter());
        sEnum = refData.getCollectors().getEnumerator();
        while (sEnum.moveNext())
        {
            collector = sEnum.current();
            if (!collector.getEDT())
            {
                continue;
            }
            tmpLookup.PageID = Page.parmId();
            tmpLookup.Title  = Page.parmTitle();
            tmpLookup.FieldName = collector.parmLabel();
            tmpLookup.EDTBasedOn = collector.getEDT();
            tmpLookup.insert();
        }

    }

    sysTableLookup.parmTmpBuffer(tmpLookup);
    sysTableLookup.performFormLookup();
}

