public static void lookupDataSetsForPostMethod(ClassId _classOverrideID, MethodName _methodName, FormControl _callingControl)
{
    TFMOrderPostDataSetAttribute    attribute;
    MapEnumerator                   methods = TFMFormLookupHelper::getMethodsFromAttribute(_classOverrideID, classStr(TFMOrderPostDataSetAttribute)).getEnumerator();
    SysTableLookup                  sysTableLookup  = SysTableLookup::newParameters(tablenum(TmpTableName), _callingControl);
    TmpTableName                    tmpLookup;
    SysDictClass                    DC;
    TFMPostMethodAttribute          attr;
    Array                           array;
    int                             i, j;
    DictMethod                      DM;
    Set                             addedTables = new Set(Types::String);

    DC = new SysDictClass(_classOverrideID);
    for (i = 1; i <= DC.objectMethodCnt(); i++)
    {
        DM = DC.objectMethodObject(i);
        array = DM.getAttributes(classStr(TFMPostMethodAttribute));
        if (array != null)
        {
            for (j = 1; j <= array.lastIndex(); j++)
            {
                attr = array.value(j);

                addedTables.add(attr.name());
            }
        }
    }

    sysTableLookup.addLookupfield(fieldnum(TmpTableName, TableName),true);

    tmpLookup.setTmp();
    while (methods.moveNext())
    {
        attribute = methods.currentValue();
        if (!addedTables.in(attribute.name()))
        {
            //Not applicable for this posting method
            continue;
        }

        tmpLookup.TableName  = attribute.name();
        tmpLookup.insert();
    }

    // BP deviation documented
    sysTableLookup.parmTmpBuffer(tmpLookup);
    sysTableLookup.performFormLookup();
}

