public static Map getAllMethodsFromAttribute(ClassId _classOverrideID, ClassName _attributeClassName, boolean _returnDictMethod = false)
{
    Map                             retSet = new Map(Types::String, Types::Class);
    SysDictClass                    DC = new SysDictClass(_classOverrideID);
    Object                          attr;
    Array                           array;
    int                             i, j;
    SysDictMethod                   DM;
    SetEnumerator                   sEnum = DC.objectMethodSet(true).getEnumerator();
    while (sEnum.moveNext())
    {
        DM = new SysDictMethod(UtilElementType::ClassInstanceMethod, _classOverrideID, sEnum.current());
        array = DM.getAttributes(_attributeClassName);
        if (array != null && array.lastIndex())
        {
            for (j = 1; j <= array.lastIndex(); j++)
            {
                attr = array.value(j);
                retSet.insert(DM.name(),_returnDictMethod ? DM : attr );

            }
        }
    }
    return retSet;
}

public static Map getMethodsFromAttribute(ClassId _classOverrideID, ClassName _attributeClassName, boolean _returnDictMethod = false)
{
    Map                             retSet = new Map(Types::String, Types::Class);
    DictClass                       DC = new DictClass(_classOverrideID);
    Object                          attr;
    Array                           array;
    int                             i, j;
    DictMethod                      DM;

    for (i = 1; i <= DC.objectMethodCnt(); i++)
    {
        DM = DC.objectMethodObject(i);
        array = DM.getAttributes(_attributeClassName);
        if (array != null && array.lastIndex())
        {
            for (j = 1; j <= array.lastIndex(); j++)
            {
                attr = array.value(j);
                retSet.insert(DM.name(),_returnDictMethod ? DM : attr );

            }
        }
    }
    return retSet;
}

public static void lookupTableFieldNames(TableName _tableName, FormControl _callingControl, boolean _appendToTableName = false, boolean _addDisplayMethods = false)
{
    SysTableLookup              sysTableLookup  = SysTableLookup::newParameters(tablenum(TmpSysTableField), _callingControl);
    Map                         fieldsOnTable   = TFMHelper::fieldsOnTable(_tableName);
    MapEnumerator               mEnum           = fieldsOnTable.getEnumerator();
    SetEnumerator				sEnum;
    TmpSysTableField            tmpLookup;
    int							i;

    sysTableLookup.addLookupfield(fieldnum(TmpSysTableField, FieldName),true);

    tmpLookup.setTmp();

    while (mEnum.moveNext())
    {

        tmpLookup.FieldName = (_appendToTableName ? _tableName + '.' : '' ) + mEnum.currentKey();
        tmpLookup.FieldID   = i;
        tmpLookup.insert();
        i++;
    }
    if (_appendToTableName)
    {
        tmpLookup.FieldName = _tableName;
        tmpLookup.FieldID   = -500;
        tmpLookup.insert();
    }
    if (_addDisplayMethods)
    {
        sEnum = TFMFormLookupHelper::displayMethodsOnTable(_tableName).getEnumerator();
        while (sEnum.moveNext())
        {
            tmpLookup.FieldName = (_appendToTableName ? _tableName + '.' : '' ) + sEnum.current() + '()';
            tmpLookup.FieldID   = i;
            tmpLookup.insert();
            i++;
        }
    }

    // BP deviation documented
    sysTableLookup.parmTmpBuffer(tmpLookup);
    sysTableLookup.performFormLookup();

}

