public static Set displayMethodsOnTable(TableName _tableName)
{
    DictTable   dictTable = new DictTable(tableName2Id(_tableName));
    DictMethod  method;
    int         noOfDispMethods = dictTable.objectMethodCnt();
    int         i;
    Set         retSet = new Set(Types::String);
    for (i=1; i< noOfDispMethods+1; i++)
    {
        method = dictTable.objectMethodObject(i);

        if (method.displayType() == DisplayFunctionType::Get)
        {
            retSet.add(method.name());
        }
    }
    return retSet;
}

/// <summary>
/// Returns a set with the parm methods on a given class. It can return a set of either method names as a string (which is the standard), or a set with SysDictMethod instances of each method.
/// </summary>
/// <param name = "_className">Name of the class to find parm methods for.</param>
/// <param name = "_onlyStrings">Set to true, if it should only return parm methods that returns string types.</param>
/// <param name = "_returnType">Set to either Types::String (default) or types::Class to get method names as a string (which is the standard), or a set with SysDictMethod instances of each method in the returnd set</param>
/// <returns>A set of parm methods on the class.</returns>
public static Set parmMethodsOnClass(ClassId _classId, boolean _onlyStrings = false, Types _returnType = Types::String)
{
    SysDictClass    dictClass = new SysDictClass(_classId);
    SysDictMethod   dm;
    str             method;
    Set             noOfMethods = dictClass.objectMethodSet(true);
    SetEnumerator   sEnum = noOfMethods.getEnumerator();
    Set             retSet = new Set(_returnType);
    boolean         isParm = false;

    while (sEnum.moveNext())
    {
       method = sEnum.current();
       isParm = 'parm' == subStr(method,1,4);

        if ((_onlyStrings || _returnType == Types::Class) && isParm)
        {
            dm = new SysDictMethod(UtilElementType::ClassInstanceMethod,_classId,method);
            if (_onlyStrings && (dm.returnType() == Types::String || (dm.returnTypeName() && new SysDictType(dm.returnId()).baseType() == Types::String)))
            {
                retSet.add(method);
            }
            else
            {
                retSet.add(dm);
            }
        }
        else if (isParm)
        {
            retSet.add(method);
        }
    }
    return retSet;
}

/// <summary>
/// Returns the TFMPageActionAttribute
/// </summary>
/// <param name = "methodName"></param>
/// <param name = "configuration"></param>
/// <returns></returns>
public static TFMPageActionAttribute IsDefinedAsPageActionAttribute(str xPath, TFMPageConfiguration configuration)
{
    TFMPageConfigurationAttributeAttribute	configAttr;
    TFMPageActionAttribute                  actionAttr;
    SysDictMethod			                DM;
    SetEnumerator                           methodSet;

    if(!configuration)
    {
        return null;
    }

    ClassId configurationClassId = classIdGet(configuration);
    methodSet = TFMFormLookupHelper::parmMethodsOnClass(configurationClassId).getEnumerator();
    while (methodSet.moveNext())
    {
        DM = new SysDictMethod(UtilElementType::ClassInstanceMethod,configurationClassId, methodSet.current());
        configAttr = DM.getAttribute(classStr(TFMPageConfigurationAttributeAttribute));

        if(configAttr && configAttr.parmXPath() == xPath)
        {
            actionAttr = DM.getAttribute(classStr(TFMPageActionAttribute));
            if(actionAttr)
            {
                return actionAttr;
            }
        }
    }
    return null;
}

