public static str removeParmFromName(str _name)
{
    str name = _name;
    if(strScan(name, 'parm', 0, 10) > 0)
    {
        name =  subStr(name,5,strLen(name));
        name = strLwr(subStr(name, 0, 1)) + subStr(name, 2, 1000000);
        return name;
    }
    return name;
}

