private static Set staticMethodsOnClass(ClassName _className)
{
    DictClass   dictClass = new DictClass(className2Id(_className));
    DictMethod  method;
    int         noOfMethods = dictClass.staticMethodCnt();
    int         i, j;
    Types       baseType;
    Set         retSet = new Set(Types::String);


    #ifnot.isAX6
    boolean     allVarsUsable;
    for (i=1; i< noOfMethods+1; i++)
    {
        method = dictClass.staticMethodObject(i);

        allVarsUsable = true;
        if (method.accessSpecifier() == AccessSpecifier::public)
        {
            for (j = 1; j <= method.parameterCnt(); j++)
            {
                baseType = method.parameterType(j);
                if (baseType == Types::UserType && method.parameterTypeName(j))
                {
                    baseType = new DictType(extendedTypeName2Id(method.parameterTypeName(j))).baseType();
                }
                allVarsUsable = allVarsUsable && TFMFormLookupHelper::isTypeAllowed(baseType);
            }
            baseType = method.returnType();
            if (baseType == Types::UserType && method.returnTypeName())
            {
                baseType = new DictType(extendedTypeName2Id(method.returnTypeName())).baseType();
            }
            if (allVarsUsable && TFMFormLookupHelper::isTypeAllowed(baseType))
            {
                retSet.add(method.name());
            }
        }
    }
    #endif
    return retSet;
}

private static boolean isTypeAllowed(Types _type)
{
    boolean isAllowed;

    switch (_type)
    {
        case Types::Date :
        case Types::Enum :
        case Types::Int64 :
        case Types::Integer :
        case Types::Real :
        case Types::Record :
        case Types::String :
        case Types::Time :
        case Types::UtcDateTime :
            isAllowed = true;
            break;
        default :
            isAllowed = false;
            break;
    }

    return isAllowed;
}

