/// <summary>
/// Checks if the labelFileId is an old style. Meaning it begins with @. The new format does not start with @ but only has text e.g 'TheLabel' but then the LabelFile is added to it. e.g. @TFM:TheLabel.
/// </summary>
/// <param name = "_labelFileId"></param>
/// <returns>True, if using the old style</returns>
public static boolean isAOldStyleLabelFile(str _labelFileId)
{
    boolean result;
    str regex = '^@.*';
    if(System.Text.RegularExpressions.Regex::IsMatch(_labelFileId, regex))
    {
        result = true;
    }
    return result;
}

