/// <summary>
/// Creates the label file values for the lookup in the database.
/// </summary>
/// <returns>The TFMTranslationLabbelIDLookupTable</returns>
public static void createLabelFileLabelIdTranslationTable(str _labelFiles, boolean runAsync = true, boolean waitForCompletion =  false)
{
    System.Threading.Tasks.Task task;
    System.Threading.Tasks.Task[] tasks;
    List labelFilesList = strSplit(_labelFiles, ';');
    ListEnumerator labelFilesListEnum = labelFilesList.getEnumerator();
    tasks = new System.Threading.Tasks.Task[labelFilesList.elements()]();
    int counter = 0;
    while(labelFilesListEnum.moveNext())
    {
        if(runAsync)
        {
            task = runAsync(classNum(TFMFormLookupHelper), staticMethodStr(TFMFormLookupHelper,createLabelIDTranslationLookupForLabelFileAsync), [labelFilesListEnum.current()], System.Threading.CancellationToken::None, classNum(TFMFormLookupHelper), staticMethodStr(TFMFormLookupHelper,ClassCallBackTest));
            tasks.Set(counter, task);
        }
        else
        {
            TFMFormLookupHelper::createLabelIDTranslationLookupForLabelFileAsync([labelFilesListEnum.current()]);
        }
        counter++;
    }

    if(waitForCompletion) // wait until all tasks are done. This is usefull when the jobs runs in a batch and should not return before it is done.
    {
        System.Threading.Tasks.Task::WaitAll(tasks);
    }

}

protected static void createLabelIDTranslationLookupForLabelFileAsync(container _conLabelFileName)
{
    anytype dLabels;
    TFMTranslationLabelIdLookupTable     tmpLookup;
    boolean existingCheck;
    System.Collections.IDictionaryEnumerator de;
    System.Globalization.CultureInfo cInfo = new System.Globalization.CultureInfo('en-US');
    str labelFileName = conPeek(_conLabelFileName, 1);

    dLabels = Microsoft.Dynamics.Ax.Xpp.LabelHelper::GetAllLabels(labelFileName, cInfo);
    if(dLabels)
    {
        de = dLabels.getEnumerator();
        while (de.moveNext())
        {
            existingCheck = TFMTranslationLabelIdLookupTable::checkExisting(de.Value);
            if(!existingCheck)
            {
                tmpLookup.LabelFile = labelFileName;
                tmpLookup.LabelId = de.Key;
                tmpLookup.LabelString = de.Value;
                if(TFMFormLookupHelper::isAOldStyleLabelFile(de.Key))
                {
                    tmpLookup.LookupId = de.Key;
                }
                else
                {
                    tmpLookup.LookupId = strFmt('@%1:%2', labelFileName, de.Key);
                }
                ttsbegin;
                tmpLookup.doInsert();
                ttscommit;
            }
        }
    }
}

public static Map AllMenus()
{
    DictClass           dc = new DictClass(classnum(TFMDocumentHandler));
    DictClass           subClass;
    List                extendingClasses = dc.extendedBy(true);
    ListEnumerator      lEnum = extendingClasses.getEnumerator();
    Object              docHand;
    container           menuContainer;
    int                 counter;
    int                 length;
    TFMMenu             menu;
    TFMMenuDescription  description;
    boolean             add2menu;
    str                 menuIcon;
    TFMDeltaPages       qPages;
    TFMMenuAttribute    menuAttribute;
    Array               arr = DictClass::getAttributedClasses(classStr(TFMMenuAttribute));
    Array               attributeArray;
    int                 attrCount;
    Map					Menus = new Map(Types::String, Types::String);


    while (lEnum.moveNext())
    {
        subClass = new DictClass(lEnum.current());
        if (subClass == null || subClass.isAbstract())
        {
            continue;
        }
        docHand = subClass.makeObject() as TFMDocumentHandler;
        menuContainer = subClass.callObject(methodStr(TFMDocumentHandler,registerMenu),docHand);
        if (menuContainer == conNull())
        {
            continue;
        }
        counter = 1;
        length = conLen(menuContainer);
        while(counter <= length)
        {

            [menu, description, add2menu, menuIcon] = conpeek(menuContainer,counter);
            Menus.insert(menu,description);
            counter++;
        }
    }
    while select qPages
    {
        Menus.insert(qPages.Name,qPages.Name);
    }
    for (counter = 1; counter <= arr.lastIndex(); counter++)
    {
        dc = new DictClass(arr.value(counter));
        attributeArray = dc.getAttributes(classStr(TFMMenuAttribute));
        for (attrCount = 1; attrCount <= attributeArray.lastIndex(); attrCount++)
        {
            menuAttribute = attributeArray.value(attrCount);

            if (menuAttribute.parmMainMenuEnabled())
            {
                Menus.insert(menuAttribute.parmName(),menuAttribute.parmLabel());
            }
        }
    }

    return Menus;
}

