public static void lookupServiceIDs(FormControl _callingControl)
{
    SysTableLookup      sysTableLookup  = SysTableLookup::newParameters(tablenum(tmpUserRequest), _callingControl);
    ResourceNode        node;

    tmpUserRequest      tmpLookup;
    BinData             binData = new BinData();
    str                 content;
    int					startPos = 1,EndPos;
    str					strTosearchFor = '<service id="';
    binData.setData(SysResource::getResourceNodeData(node));
    content = binData.getStrData();
    sysTableLookup.addLookupfield(fieldNum(tmpUserRequest,Name),true);

    tmpLookup.setTmp();
    do
    {
        startPos = strScan(content,strTosearchFor,startPos,strLen(content));
        EndPos   = strScan(content,'"',startPos + strLen(strTosearchFor) + 2,strLen(content));
        if (startPos > 1)
        {
            startPos = startPos + strLen(strTosearchFor);
            tmpLookup.Name = subStr(content,startPos,EndPos - startPos);
        }
        else
        {
            startPos = -5;
        }
        tmpLookup.doinsert();
    }
    while (startPos > 0);
    sysTableLookup.parmTmpBuffer(tmpLookup);
    sysTableLookup.performFormLookup();
}

