    Set								produDims = TFMHelper::fieldGroupToSet(tableNum(InventDim),tableFieldGroupStr(InventDim, ProductDimensions));
    Set								trackDims = TFMHelper::fieldGroupToSet(tableNum(InventDim),tableFieldGroupStr(InventDim, TrackingDimensions));
    FieldName						localFieldName;
    SysTableLookup                  sysTableLookup  = SysTableLookup::newParameters(tablenum(TmpTableName), _callingControl);
    TmpTableName                    tmpLookup;
    Set                             combiSet = Set::union(Set::union(storeDims, produDims),trackDims);
    SetEnumerator			        sEnum = combiSet.getEnumerator();

    sysTableLookup.addLookupfield(fieldNum(TmpTableName,TableName),true);


    tmpLookup.setTmp();
    while (sEnum.moveNext())
    {
        localFieldName = sEnum.current();

        if (!parm.(InventDim::dim2dimParm(fieldName2Id(tableNum(InventDim),sEnum.current()))))
        {
            continue;
        }
        tmpLookup.TableName  = localFieldName;
        tmpLookup.insert();
    }

    // BP deviation documented
    sysTableLookup.parmTmpBuffer(tmpLookup);
    sysTableLookup.performFormLookup();

}

public static Set getDeviceIcons(str _configFile)
{
    int posStart;
    int posEnd;
    Set retSet = new Set(Types::String);

    posStart = strScan(_configFile,'icon=',1,strLen(_configFile));

    while (posStart)
    {
        posStart = strScan(_configFile,'"',posStart,strLen(_configFile));
        posEnd = strScan(_configFile,'"',posStart+1,strLen(_configFile));
        if (posStart && posEnd)
        {
            retSet.add(subStr(_configFile,posStart+1,posEnd-posStart-1));
        }
        posStart = strScan(_configFile,'icon=',posEnd,strLen(_configFile));
    }
    return retSet;
}

private static Set getDeviceLabels(str _configFile)
{
    System.Text.RegularExpressions.Match myMatch;
    System.String sysStrOut;
    str strOut;
    str regex;
    Set retSet = new Set(Types::String);

    regex = @'(?s)(?<=@{).*?(?=})';

    myMatch = System.Text.RegularExpressions.Regex::Match(_configFile, regex);


    while (myMatch.get_Success())
    {
        sysStrOut = myMatch.get_Value();
        strOut = sysStrOut; // marshall data types
        if (!retSet.in(strOut))
        {
            retSet.add(strOut);
        }
        myMatch = myMatch.NextMatch();
    }
    return retSet;
}

